WITH order_items_by_order AS (SELECT order_id, SUM(quantity * unit_price) AS revenue, MIN(unit_price) AS min_unit_price FROM order_items WHERE product_id IS NOT NULL GROUP BY order_id) SELECT o.id, o.shipping_fee, o.amount, oibo.revenue, oibo.min_unit_price FROM orders o INNER JOIN order_items_by_order oibo ON o.id = oibo.order_id WHERE oibo.revenue > 72 ORDER BY o.shipping_fee DESC, revenue DESC;
